// Prettier plugin entry. See docs/adr/0001 for the pipeline shape.

import { tokenize } from './edge-lex.js'
import { parseEdge } from './edge-parse.js'
import { parseMaskedHtml } from './parse-html.js'
import { splice } from './splice.js'
import { prepare } from './prepare.js'
import { printDocument } from './print.js'
import { preprocess } from './preprocess.js'

const EDGE_AST_FORMAT = 'edge-ast'

export const languages = [
  {
    name: 'Edge',
    parsers: ['edge'],
    extensions: ['.edge'],
    vscodeLanguageIds: ['edge'],
  },
]

export const options = {
  edgeMustacheSpacing: {
    since: '0.2.0',
    category: 'Edge',
    type: 'int',
    default: 1,
    description: 'Number of spaces inside mustache delimiters. 1 → {{ x }}, 0 → {{x}}.',
  },
  edgeAttributeQuotes: {
    since: '0.2.0',
    category: 'Edge',
    type: 'choice',
    default: 'double',
    choices: [
      { value: 'double', description: 'Use double quotes (")' },
      { value: 'single', description: "Use single quotes (')" },
      { value: 'preserve', description: 'Preserve the original quote character' },
    ],
    description: 'Quote character for HTML attribute values.',
  },
  edgeBlankLinesInBlocks: {
    since: '0.2.0',
    category: 'Edge',
    type: 'int',
    default: 1,
    description: 'Maximum number of blank lines preserved between block-level siblings.',
  },
}

export const parsers = {
  edge: {
    async parse(text, options) {
      try {
        const { source: pp, rawTexts, rawBlocks, tagArgs } = preprocess(text)
        const tokens = tokenize(pp)
        const { masked, sideTable } = parseEdge(pp, tokens, tagArgs)
        const htmlAst = parseMaskedHtml(masked)
        const mixed = splice(htmlAst, sideTable, rawBlocks)
        restoreRawTexts(mixed, rawTexts)
        await prepare(mixed, options)
        return { type: 'EdgeDocument', children: mixed, source: text }
      } catch (err) {
        // Strict v1 error policy: any parse failure → return source
        // unchanged. The printer notices via __passthrough and emits the
        // original text. The error is attached for debugging via
        // EDGE_DEBUG_PARSE=1.
        if (process.env.EDGE_DEBUG_PARSE === '1') {
          console.error(`[edge-plugin] parse failed: ${err?.message ?? err}\n  ${err?.stack ?? ''}`)
        }
        return {
          type: 'EdgeDocument',
          children: [],
          source: text,
          __passthrough: true,
          __error: err,
        }
      }
    },
    astFormat: EDGE_AST_FORMAT,
    locStart: () => 0,
    locEnd: (node) => node.source?.length ?? 0,
  },
}

export const printers = {
  [EDGE_AST_FORMAT]: {
    print(path, options) {
      const node = path.node ?? path.getValue()
      if (node.__passthrough) return ensureTrailingNewline(node.source)
      return printDocument(node.children, options)
    },
  },
}

function ensureTrailingNewline(s) {
  return s.endsWith('\n') ? s : s + '\n'
}

// After splice, walk the tree and restore raw-text element bodies that
// preprocess() stashed in `rawTexts`. The sentinel lives as an HTMLText
// child whose value is `__EDGE_RAW_N__`.
function restoreRawTexts(nodes, rawTexts) {
  for (const node of nodes) restoreNode(node, rawTexts)
}

function restoreNode(node, rawTexts) {
  if (!node || typeof node !== 'object') return
  if (node.type === 'HTMLComment') {
    // PI sentinel: preprocess swapped `<?xml …?>` for `<!--__EDGE_PI_N__-->`
    // so angular-html-parser would accept it. Convert the comment back
    // into an HTMLProcInst node carrying the original source.
    const m = /^__EDGE_PI_(\d+)__$/.exec((node.value ?? '').trim())
    if (m) {
      const original = rawTexts.get(Number(m[1]))
      if (original != null) {
        node.type = 'HTMLProcInst'
        node.value = original
      }
    }
    return
  }
  if (node.type === 'HTMLElement') {
    if (node.children && node.children.length === 1) {
      const c = node.children[0]
      if (c.type === 'HTMLText') {
        const m = /^__EDGE_RAW_(\d+)__$/.exec(c.value)
        if (m) {
          const original = rawTexts.get(Number(m[1]))
          if (original != null) c.value = original
        }
      }
    }
    for (const c of node.children ?? []) restoreNode(c, rawTexts)
    return
  }
  if (node.type === 'EdgeBlock') {
    for (const b of node.branches) restoreRawTexts(b.body ?? [], rawTexts)
  }
}
